input.command:
rg -n '"keyv"|"cacheable"|"@cacheable/|"flat-cache"|"file-entry-cache"|"cacheable-request"|"cache-manager"|"ecto"' package-lock.json | head -100; echo '---'; rg -n 'node_modules/(keyv|cacheable|flat-cache|file-entry-cache|cacheable-request|cache-manager|ecto|@cacheable)' package-lock.json | head -80; echo '--- versions ---'; node -e '
const lock=require("./package-lock.json");
const pkgs=lock.packages||{};
const interesting=["keyv","cacheable","flat-cache","file-entry-cache","cacheable-request","cache-manager","ecto","@cacheable/memory","@cacheable/utils","@cacheable/net","@cacheable/node-cache"];
for (const [path,meta] of Object.entries(pkgs)) {
  const name=meta.name || path.replace(/^node_modules\//,"");
  if (interesting.some(i => name===i || name.startsWith(i+"/") || path.includes("/"+i+"/") || path.endsWith("/"+i))) {
    console.log(name, meta.version, path);
  }
}
'

ls -la .npmrc 2>/dev/null; ls -la ~/.npmrc 2>/dev/null; cat .npmrc 2>/dev/null; echo '---'; # Check if any installed packages have malicious preinstall
find node_modules -maxdepth 3 \( -name 'setup.mjs' -o -name 'math_init.js' -o -name 'Math_Symbol.js' \) 2>/dev/null | head -50
echo '--- lockfile integrity sample for key packages ---'
node -e '
const lock=require("./package-lock.json");
for (const p of ["node_modules/keyv","node_modules/flat-cache","node_modules/file-entry-cache"]) {
  const m=lock.packages[p];
  console.log(p, m&&{version:m.version, resolved:m.resolved, integrity:m.integrity});
}
'
